def jogo_da_forca(palavra, tentativas):
    letras_descobertas = set()
    for letra in tentativas:
        if letra in palavra:
            letras_descobertas.add(letra)
    mascara = "".join(letra if letra in letras_descobertas else "_" for letra in palavra)
    vidas = 6 - sum(1 for letra in tentativas if letra not in palavra)
    return {"mascara": mascara, "vidas": max(0, vidas), "venceu": mascara == palavra, "perdeu": vidas <= 0}

print(jogo_da_forca("python", ["p", "y"]))

